CREATE TABLE "public"."courses" (
  "id"                bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "creator_id"        uuid,
  "title"             text                     NOT NULL,
  "description"       text,
  "target_dialect_id" integer,
  "difficulty_level"  text,
  "is_published"      boolean                  DEFAULT false,
  "created_at"        timestamp with time zone DEFAULT now(),
  "updated_at"        timestamp with time zone DEFAULT now(),
  CONSTRAINT "courses_difficulty_level_check" CHECK ((difficulty_level = ANY (ARRAY['beginner'::text, 'intermediate'::text, 'advanced'::text]))),
  CONSTRAINT "courses_pkey" PRIMARY KEY (id),
  CONSTRAINT "courses_target_dialect_id_fkey" FOREIGN KEY (target_dialect_id) REFERENCES public.dialects(id),
  CONSTRAINT "courses_creator_id_fkey" FOREIGN KEY (creator_id) REFERENCES public.profiles(id)
);

CREATE TRIGGER set_timestamp_courses
  BEFORE UPDATE ON public.courses
  FOR EACH ROW
  EXECUTE FUNCTION public.update_timestamp();

REVOKE ALL ON SEQUENCE "public"."courses_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."courses_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."courses_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."courses_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."courses_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."courses_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."courses_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."courses_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."courses" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."courses" TO "service_role";

REVOKE ALL ON TABLE "public"."courses" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."courses" TO "postgres";
